-- REVIEW ONLY: do not apply before approval.
begin;
create or replace function public.protect_historical_alias_identity() returns trigger language plpgsql as $$
begin
  if new.source_system is distinct from old.source_system or new.source_label is distinct from old.source_label
     or to_jsonb(new)->>tg_argv[0] is distinct from to_jsonb(old)->>tg_argv[0]
     or new.provenance is distinct from old.provenance then
    raise exception 'historical alias identity, target, and provenance are immutable';
  end if;
  if old.active and not new.active then new.deactivated_at := coalesce(new.deactivated_at,now()); end if;
  if not old.active and new.active then new.deactivated_at := null; end if;
  return new;
end $$;
revoke all on function public.protect_historical_alias_identity() from public, anon, authenticated;
alter table public.historical_location_aliases add column if not exists source_system text;
alter table public.historical_location_aliases add column if not exists provenance jsonb;
alter table public.historical_location_aliases add column if not exists review_status text;
alter table public.historical_location_aliases add column if not exists active boolean;
alter table public.historical_location_aliases add column if not exists reviewed_at timestamptz;
alter table public.historical_location_aliases add column if not exists reviewed_by text;
alter table public.historical_location_aliases add column if not exists deactivated_at timestamptz;
update public.historical_location_aliases set source_system=coalesce(source_system,'legacy_unscoped'), provenance=coalesce(provenance,jsonb_build_object('migration','legacy alias backfill')), review_status=coalesce(review_status,'approved_legacy'), active=coalesce(active,true), reviewed_at=coalesce(reviewed_at,updated_at,created_at,now()), reviewed_by=coalesce(reviewed_by,'legacy_migration');
