alter table public.historical_location_aliases drop constraint if exists historical_location_aliases_source_check;
alter table public.historical_location_aliases add constraint historical_location_aliases_source_check check (btrim(source_system)<>'' and btrim(source_label)<>'');
alter table public.historical_location_aliases drop constraint if exists historical_location_aliases_pkey;
alter table public.historical_location_aliases add constraint historical_location_aliases_pkey primary key (source_system, source_label);
create index if not exists historical_location_aliases_location_id_idx on public.historical_location_aliases(location_id);
drop trigger if exists protect_historical_alias_identity on public.historical_location_aliases;
create trigger protect_historical_alias_identity before update on public.historical_location_aliases for each row execute function public.protect_historical_alias_identity('location_id');
revoke all privileges on table public.historical_location_aliases from anon, authenticated;
